# ---------------------------------------------------------------- data copy (legacy -> v2)

def _slug(name, used):
    import re
    base = re.sub(r"[^a-z0-9]+", "-", (name or "").lower().replace("'", "")).strip("-") or "account"
    slug, n = base, 2
    while slug in used:
        slug, n = f"{base}-{n}", n + 1
    used.add(slug)
    return slug


def _copy_legacy_data():
    """Move webdev clients/jobs/recurring payments into accounts/jobs/subscriptions/payments.
    hapitech.report tenants and pricing tiers are intentionally not carried over (feature removed)."""
    import datetime as dt
    conn = op.get_bind()
    insp = sa.inspect(conn)
    existing = set(insp.get_table_names())
    now = dt.datetime.utcnow()
    used, acct_for_webdev, acct_for_client = set(), {}, {}

    if "webdev_clients" in existing:
        for r in conn.execute(sa.text("SELECT * FROM webdev_clients ORDER BY id")).mappings():
            slug = _slug(r["name"], used)
            res = conn.execute(sa.text(
                "INSERT INTO accounts (name, slug, kind, status, domain, contact_name, contact_email, contact_phone, "
                "notes, created_at, updated_at) VALUES (:n, :s, 'client', :st, :d, :cn, :ce, :cp, :no, :c, :u)"),
                dict(n=r["name"], s=slug, st=r.get("status") or "active", d=r.get("domain"),
                     cn=r.get("contact_name"), ce=r.get("contact_email"), cp=r.get("contact_phone"),
                     no=r.get("notes"), c=r.get("created_at") or now, u=r.get("updated_at") or now))
            acct_for_webdev[r["id"]] = res.lastrowid if res.lastrowid else conn.execute(
                sa.text("SELECT id FROM accounts WHERE slug=:s"), dict(s=slug)).scalar()

    if "clients" in existing:
        for r in conn.execute(sa.text("SELECT * FROM clients ORDER BY id")).mappings():
            match = conn.execute(sa.text("SELECT id FROM accounts WHERE lower(name)=lower(:n)"),
                                 dict(n=r["name"])).scalar()
            if match is None:
                slug = _slug(r["name"], used)
                conn.execute(sa.text(
                    "INSERT INTO accounts (name, slug, kind, status, contact_email, contact_phone, created_at, "
                    "updated_at) VALUES (:n, :s, 'client', :st, :e, :p, :c, :c)"),
                    dict(n=r["name"], s=slug, st=r.get("status") or "active", e=r.get("primary_email"),
                         p=r.get("phone"), c=now))
                match = conn.execute(sa.text("SELECT id FROM accounts WHERE slug=:s"), dict(s=slug)).scalar()
            acct_for_client[r["id"]] = match

    # users: role client -> owner; link to the account their old client_id pointed at
    for r in conn.execute(sa.text("SELECT id, email, role, client_id FROM users")).mappings():
        role = "admin" if r["role"] == "admin" else "owner"
        conn.execute(sa.text("UPDATE users SET role=:r, account_id=:a WHERE id=:i"),
                     dict(r=role, a=acct_for_client.get(r["client_id"]), i=r["id"]))

    if "webdev_jobs" in existing:
        type_map = {"website_build": "build", "maintenance": "change", "hosting": "hosting", "design": "change",
                    "seo_audit": "other"}
        status_map = {"pending": "booked", "in_progress": "in_progress", "completed": "done",
                      "cancelled": "cancelled"}
        for r in conn.execute(sa.text("SELECT * FROM webdev_jobs ORDER BY id")).mappings():
            acct = acct_for_webdev.get(r["client_id"])
            if not acct:
                continue
            res = conn.execute(sa.text(
                "INSERT INTO jobs (account_id, title, type, status, price_gbp, notes, created_at, updated_at) "
                "VALUES (:a, :t, :ty, :st, :p, :no, :c, :u)"),
                dict(a=acct, t=r["title"], ty=type_map.get(r.get("job_type"), "other"),
                     st=status_map.get(r.get("status"), "booked"), p=r.get("price_gbp") or 0,
                     no=r.get("description"), c=r.get("created_at") or now, u=r.get("updated_at") or now))
            job_id = res.lastrowid or conn.execute(sa.text("SELECT max(id) FROM jobs")).scalar()
            if (r.get("payment_status") or "").upper() == "PAID" and float(r.get("price_gbp") or 0) > 0:
                paid = r.get("updated_at") or r.get("created_at") or now
                paid = paid.date() if hasattr(paid, "date") else str(paid)[:10]
                conn.execute(sa.text(
                    "INSERT INTO payments (account_id, job_id, amount_gbp, paid_at, method, ref, created_at) "
                    "VALUES (:a, :j, :amt, :d, 'other', 'migrated from webdev_jobs', :c)"),
                    dict(a=acct, j=job_id, amt=r["price_gbp"], d=paid, c=now))

    if "recurring_payments" in existing:
        for r in conn.execute(sa.text(
                "SELECT * FROM recurring_payments WHERE client_type='webdev' ORDER BY id")).mappings():
            acct = acct_for_webdev.get(r["client_id"])
            if not acct:
                continue
            conn.execute(sa.text(
                "INSERT INTO subscriptions (account_id, title, amount_gbp, interval, next_due, status, created_at, "
                "updated_at) VALUES (:a, :t, :amt, :i, :nd, :st, :c, :c)"),
                dict(a=acct, t=r["title"], amt=r.get("amount_gbp") or 0,
                     i="yearly" if (r.get("billing_interval") or "").startswith("year") else "monthly",
                     nd=r.get("next_due_date"), st="active" if (r.get("status") or "active") == "active" else "cancelled",
                     c=r.get("created_at") or now))

    if "monthly_payment_status" in existing:
        for r in conn.execute(sa.text(
                "SELECT * FROM monthly_payment_status WHERE entity_type='webdev' AND status='PAID'")).mappings():
            acct = acct_for_webdev.get(r["entity_id"])
            if not acct:
                continue
            paid = r.get("marked_paid_at") or (str(r["month"]) + "-01")
            paid = paid.date() if hasattr(paid, "date") else str(paid)[:10]
            conn.execute(sa.text(
                "INSERT INTO payments (account_id, amount_gbp, paid_at, method, ref, created_at) "
                "VALUES (:a, :amt, :d, 'other', :ref, :c)"),
                dict(a=acct, amt=r.get("amount_gbp") or 0, d=paid, ref=f"monthly {r['month']} (migrated)", c=now))
